 * 4. Rate limiting
 * Protects against brute force and DoS attacks
 */
const apiLimiter = rateLimit({
  windowMs: config.RATE_LIMIT_WINDOW_MS,
  max: config.RATE_LIMIT_MAX,
  message: { 
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: Math.ceil(config.RATE_LIMIT_WINDOW_MS / 1000),
  },
  standardHeaders: true, // Send `RateLimit-*` headers
  legacyHeaders: false,  // Disable `X-RateLimit-*` headers
  handler: (req, res, next, options) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json(options.message);
  },
  // Skip rate limiting for certain conditions
  skip: (req) => {
    // Skip for health checks
    return req.path === '/health';
  },
});

// Apply rate limiting to API routes
app.use('/api', apiLimiter);

// Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Only 5 login attempts per window
  skipSuccessfulRequests: true, // Don't count successful logins
  message: { error: 'Too many login attempts. Please try again later.' },
});

app.use('/auth', authLimiter);

/**
 * 5. Data sanitization
 * Protects against NoSQL injection and XSS
 */
app.use(mongoSanitize()); // Sanitize MongoDB operators
app.use(xss()); // Sanitize user input (HTML sanitization)

/**
 * 6. Prevent parameter pollution
 * Prevents query string parameter pollution attacks
 */
app.use(hpp({
  whitelist: ['page', 'limit', 'sort', 'fields'], // Allow duplicates for these
}));

/**
 * 7. Request logging
 */
if (config.IS_PRODUCTION) {
  app.use(morgan('combined', {
    skip: (req) => req.path === '/health',
    stream: { write: (msg) => logger.http(msg.trim()) },
  }));
} else {
  app.use(morgan('dev', {
    skip: (req) => req.path === '/health',
  }));
}

/**
 * 8. Request ID for tracing (helpful for debugging)
 */
app.use((req, res, next) => {
  req.id = require('crypto').randomUUID();
  res.setHeader('X-Request-Id', req.id);
  next();
});

// ============================================================
// VALIDATION MIDDLEWARE
// ============================================================

/**
 * Validation error handler
 */
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { 
      errors: errors.array(),
      path: req.path,
      ip: req.ip,
    });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

/**
 * Sanitize and validate pagination parameters
 */
