// ROUTES
// ============================================================

/**
 * Health check endpoint
 * No authentication required - used by load balancers and monitoring
 */
app.get('/health', (req, res) => {
  // Don't log health checks - they're noisy
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: config.NODE_ENV,
  });
});

/**
 * Readiness check for Kubernetes
 */
app.get('/ready', (req, res) => {
  // Check database connection, etc.
  res.status(200).json({ status: 'ready' });
});

/**
 * Users endpoint - protected with validation
 * In production, this should require authentication
 */
app.get('/api/users', validatePagination, (req, res) => {
  const { page = 1, limit = 10 } = req.query;

  // In a real app, this would:
  // 1. Authenticate the user
  // 2. Check authorization
  // 3. Query database with pagination
  // 4. Return sanitized user data (no passwords, PII minimized)

  logger.info('Users list requested', { 
    page, 
    limit, 
    requestId: req.id,
    ip: req.ip,
  });

  // Simulated response - only expose non-sensitive data
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  // Set pagination headers
  res.set('X-Total-Count', users.length);
  res.set('X-Page-Count', 1);

  res.json({
    data: users,
    pagination: {
      page,
      limit,
      total: users.length,
    },
  });
});

/**
 * Example: POST endpoint with validation
 */
app.post('/api/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(), // Escape HTML entities
    body('email')
      .isEmail()
      .withMessage('Must be a valid email')
      .normalizeEmail() // Normalize email
      .isLength({ max: 255 })
      .withMessage('Email must be less than 255 characters'),
    body('password')
      .isLength({ min: 8, max: 128 })
      .withMessage('Password must be between 8 and 128 characters')
      .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .withMessage('Password must contain uppercase, lowercase, number, and special character'),
    // Don't return the password in the error message
    body('password').customSanitizer(() => '***REDACTED***'),
    validate,
  ],
  async (req, res) => {
    try {
      // Hash password before storing
      // const hashedPassword = await bcrypt.hash(req.body.password, config.BCRYPT_SALT_ROUNDS);

      logger.info('User creation attempted', { 
        email: req.body.email,
        requestId: req.id,
      });

      // Create user in database
      // const user = await User.create({ ...req.body, password: hashedPassword });

      res.status(201).json({
        id: 3,
        name: req.body.name,
        email: req.body.email,
      });
    } catch (error) {
      logger.error('User creation failed', { 
        error: error.message,
        requestId: req.id,
      });

      // Handle duplicate email error
      if (error.code === 'ER_DUP_ENTRY') {
        return res.status(409).json({ error: 'Email already exists' });
      }

      // Generic error - don't expose internal details
      res.status(500).json({ error: 'Failed to create user' });
    }
  }
);

/**
 * Example: Parameter validation
 */
app.get('/api/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    validate,
  ],
  (req, res) => {
    const { id } = req.params;

    // In production: fetch from database
    const user = { id, name: 'Alice' };

    if (!user) {
      logger.warn('User not found', { id, requestId: req.id });
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  }
);

// ============================================================
// ERROR HANDLING
// ============================================================

/**
 * Custom error class for operational errors
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * 404 Not Found handler
 */
app.use((req, res, next) => {
  const error = new AppError(`Cannot find ${req.method} ${req.originalUrl}`, 404);
  next(error);
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  // Log error
  logger.error('Application error', {
    message: err.message,
    stack: config.IS_DEVELOPMENT ? err.stack : undefined,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method,
    requestId: req.id,
    ip: req.ip,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Determine error message
  // In production, hide internal errors from clients
  const message = err.isOperational || !config.IS_PRODUCTION
    ? err.message
    : 'An unexpected error occurred';

  // Send error response
  res.status(statusCode).json({
    error: message,
    status: err.status || 'error',
    ...(config.IS_DEVELOPMENT && {
      stack: err.stack,
      details: err.details,
    }),
    requestId: req.id,
  });
});

// ============================================================
// GRACEFUL SHUTDOWN
// ============================================================

process.on('SIGTERM', () => {
  logger.info('SIGTERM received. Shutting down gracefully...');
  // Close server, database connections, etc.
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received. Shutting down gracefully...');
  process.exit(0);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('UNCAUGHT EXCEPTION! Shutting down...', {
    error: err.message,
    stack: err.stack,
  });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('UNHANDLED REJECTION! Reason:', { reason });
  process.exit(1);
});

// ============================================================
// START SERVER
// ============================================================

if (require.main === module) {
  const PORT = config.PORT;
  const HOST = config.HOST;

  const server = app.listen(PORT, HOST, () => {
    logger.info(`Server started`, {
      port: PORT,
      host: HOST,
      environment: config.NODE_ENV,
      pid: process.pid,
    });

    // Log security configuration
    logger.info('Security configuration:', {
      helmet: 'enabled',
      cors: config.ALLOWED_ORIGINS,
      rateLimit: `${config.RATE_LIMIT_MAX} requests per ${config.RATE_LIMIT_WINDOW_MS / 1000}s`,
      trustProxy: config.IS_PRODUCTION,
    });
  });

  // Handle server errors
  server.on('error', (err) => {
    if (err.code === 'EADDRINUSE') {
      logger.error(`Port ${PORT} is already in use`);
      process.exit(1);
    }
    throw err;
  });
}

