/**
 * Secure Secrets Management Module
 * 
 * This module provides a unified interface for accessing secrets
 * from various backends (environment variables, AWS Secrets Manager,
 * HashiCorp Vault, etc.)
 */

const crypto = require('crypto');

// Secrets backend configuration
const SECRETS_BACKEND = process.env.SECRETS_BACKEND || 'env';

/**
 * Base secrets provider interface
 */
class SecretsProvider {
  async getSecret(key) {
    throw new Error('getSecret() must be implemented');
  }

  async getSecrets(keys) {
    const results = {};
    for (const key of keys) {
      results[key] = await this.getSecret(key);
    }
    return results;
  }
}

/**
 * Environment Variables Provider
 * For local development only - NOT recommended for production
 */
class EnvSecretsProvider extends SecretsProvider {
  constructor() {
    super();
    this.requiredSecrets = new Set();
    this.loaded = false;
  }

  async getSecret(key) {
    const value = process.env[key];
    if (value === undefined) {
      console.warn(`[SECRETS] Warning: Secret '${key}' not found in environment`);
      return null;
    }
    return value;
  }

  validateSecrets(requiredKeys) {
    const missing = requiredKeys.filter(key => !process.env[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
    return true;
  }
}

/**
 * AWS Secrets Manager Provider
 * Recommended for AWS deployments
 */
class AWSSecretsManagerProvider extends SecretsProvider {
  constructor(config = {}) {
    super();
    this.region = config.region || process.env.AWS_REGION || 'us-east-1';
    this.client = null;
    this.cache = new Map();
    this.cacheTTL = config.cacheTTL || 3600000; // 1 hour default
  }

  async getClient() {
    if (!this.client) {
      // Dynamic import to avoid dependency if not used
      const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');
      this.client = new SecretsManagerClient({ region: this.region });
    }
    return this.client;
  }

  async getSecret(secretId) {
    // Check cache first
    const cached = this.cache.get(secretId);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const client = await this.getClient();
      const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

      const response = await client.send(
        new GetSecretValueCommand({ SecretId: secretId })
      );

      let value;
      if (response.SecretString) {
        value = JSON.parse(response.SecretString);
      } else if (response.SecretBinary) {
        value = Buffer.from(response.SecretBinary, 'base64').toString('utf8');
      }

      // Cache the result
      this.cache.set(secretId, { value, timestamp: Date.now() });

      // Audit log (don't log the actual secret value)
      console.log(`[SECRETS] Retrieved secret: ${secretId}`);

      return value;
    } catch (error) {
      console.error(`[SECRETS] Failed to retrieve ${secretId}:`, error.message);
      throw error;
    }
  }
}

/**
 * HashiCorp Vault Provider
 * Recommended for multi-cloud deployments
 */
class VaultSecretsProvider extends SecretsProvider {
  constructor(config = {}) {
    super();
    this.vaultAddr = config.address || process.env.VAULT_ADDR;
    this.vaultToken = config.token || process.env.VAULT_TOKEN;
    this.namespace = config.namespace || process.env.VAULT_NAMESPACE;
  }

  async getSecret(path) {
    const fetch = require('node-fetch');

    const response = await fetch(`${this.vaultAddr}/v1/${path}`, {
      method: 'GET',
      headers: {
        'X-Vault-Token': this.vaultToken,
        'X-Vault-Namespace': this.namespace,
      },
    });

    if (!response.ok) {
      throw new Error(`Vault error: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data.data?.data || data.data;
  }
}

/**
 * Google Cloud Secret Manager Provider
 */
class GCPSecretManagerProvider extends SecretsProvider {
  constructor(config = {}) {
    super();
    this.projectId = config.projectId || process.env.GOOGLE_CLOUD_PROJECT;
    this.client = null;
  }

  async getClient() {
    if (!this.client) {
      const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
      this.client = new SecretManagerServiceClient();
    }
    return this.client;
  }

  async getSecret(name) {
    const client = await this.getClient();
    const [version] = await client.accessSecretVersion({
      name: `projects/${this.projectId}/secrets/${name}/versions/latest`,
    });
    return version.payload.data.toString('utf8');
  }
}

/**
 * Secrets Manager Factory
 */
function createSecretsProvider() {
  switch (SECRETS_BACKEND.toLowerCase()) {
    case 'aws':
    case 'secretsmanager':
      return new AWSSecretsManagerProvider();

    case 'vault':
      return new VaultSecretsProvider();

    case 'gcp':
      return new GCPSecretManagerProvider();

    case 'env':
    case 'environment':
    default:
      console.warn('[SECRETS] Using environment variables - NOT recommended for production');
      return new EnvSecretsProvider();
  }
}

/**
 * Initialize secrets from the appropriate backend
 */
async function initializeSecrets() {
  const provider = createSecretsProvider();

  // Define required secrets based on environment
  const isProduction = process.env.NODE_ENV === 'production';

  const requiredSecrets = isProduction
    ? ['DATABASE_URL', 'JWT_SECRET', 'ENCRYPTION_KEY']
    : ['DATABASE_URL'];

  const optionalSecrets = [
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY',
    'ANTHROPIC_API_KEY',
    'LOGFIRE_TOKEN',
  ];

