/**
 * Secrets Management Module
 * 
 * Supports multiple secrets backends:
 * - Environment variables (development)
 * - AWS Secrets Manager (production)
 * - HashiCorp Vault (enterprise)
 * - Azure Key Vault (Azure deployments)
 * 
 * OWASP A02:2021 - Cryptographic Failures
 * OWASP A05:2021 - Security Misconfiguration
 */

const crypto = require('crypto');

// Cache for secrets (with TTL)
const secretsCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

/**
 * Secret provider interface
 */
class SecretProvider {
  async getSecret(name) {
    throw new Error('Method not implemented');
  }

  async getSecrets(names) {
    const results = {};
    for (const name of names) {
      results[name] = await this.getSecret(name);
    }
    return results;
  }
}

/**
 * Environment Variables Provider
 * Use only for development - NOT recommended for production
 */
class EnvironmentProvider extends SecretProvider {
  constructor() {
    super();
    this.warned = false;
  }

  async getSecret(name) {
    const value = process.env[name];

    // Warn about using env vars in production
    if (!this.warned && process.env.NODE_ENV === 'production') {
      console.warn('⚠️  WARNING: Using environment variables for secrets in production is not recommended. Use a secrets manager.');
      this.warned = true;
    }

    if (!value) {
      throw new Error(`Secret '${name}' not found in environment variables`);
    }

    return value;
  }
}

/**
 * AWS Secrets Manager Provider
 * Recommended for AWS deployments
 */
class AWSSecretsManagerProvider extends SecretProvider {
  constructor(options = {}) {
    super();
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.client = null;
  }

  async getClient() {
    if (!this.client) {
      // Lazy load AWS SDK
      const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
      this.client = new SecretsManagerClient({ region: this.region });
      this.GetSecretValueCommand = GetSecretValueCommand;
    }
    return this.client;
  }

  async getSecret(secretId) {
    // Check cache first
    const cached = secretsCache.get(secretId);
    if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.value;
    }

    try {
      const client = await this.getClient();
      const command = new this.GetSecretValueCommand({ SecretId: secretId });
      const response = await client.send(command);

      let value;
      if (response.SecretString) {
        value = response.SecretString;
      } else if (response.SecretBinary) {
        value = Buffer.from(response.SecretBinary, 'base64').toString('utf8');
      }

      // Parse JSON if the secret is a JSON string
      try {
        value = JSON.parse(value);
      } catch (e) {
        // Not JSON, return as-is
      }

      // Cache the result
      secretsCache.set(secretId, { value, timestamp: Date.now() });

      return value;
    } catch (error) {
      console.error(`Failed to retrieve secret '${secretId}':`, error.message);
      throw error;
    }
  }
}

/**
 * HashiCorp Vault Provider
 * Recommended for multi-cloud enterprise deployments
 */
class VaultProvider extends SecretProvider {
  constructor(options = {}) {
    super();
    this.address = options.address || process.env.VAULT_ADDR;
    this.token = options.token || process.env.VAULT_TOKEN;
    this.namespace = options.namespace || process.env.VAULT_NAMESPACE;
    this.client = null;
  }

  async getClient() {
    if (!this.client) {
      const Vault = require('node-vault')({
        endpoint: this.address,
        token: this.token,
        namespace: this.namespace,
      });
      this.client = Vault;
    }
    return this.client;
  }

  async getSecret(path) {
    const cached = secretsCache.get(path);
    if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.value;
    }

    try {
      const vault = await this.getClient();
      const result = await vault.read(path);

      secretsCache.set(path, { value: result.data, timestamp: Date.now() });

      return result.data;
    } catch (error) {
      console.error(`Failed to retrieve secret from Vault '${path}':`, error.message);
      throw error;
    }
  }
}

/**
 * Azure Key Vault Provider
 */
class AzureKeyVaultProvider extends SecretProvider {
  constructor(options = {}) {
    super();
    this.vaultUrl = options.vaultUrl || process.env.AZURE_KEY_VAULT_URL;
    this.credential = null;
    this.client = null;
  }

  async getClient() {
    if (!this.client) {
      const { DefaultAzureCredential } = require('@azure/identity');
      const { SecretClient } = require('@azure/keyvault-secrets');

      this.credential = new DefaultAzureCredential();
      this.client = new SecretClient(this.vaultUrl, this.credential);
    }
    return this.client;
  }

  async getSecret(name) {
    const cached = secretsCache.get(name);
    if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.value;
    }

    try {
      const client = await this.getClient();
      const secret = await client.getSecret(name);

      secretsCache.set(name, { value: secret.value, timestamp: Date.now() });

      return secret.value;
    } catch (error) {
      console.error(`Failed to retrieve secret from Azure Key Vault '${name}':`, error.message);
      throw error;
    }
  }
}

/**
 * Secrets Manager - Main entry point
 * Automatically selects the appropriate provider based on configuration
 */
class SecretsManager {
  constructor() {
    this.provider = this.detectProvider();
  }

  detectProvider() {
    const provider = process.env.SECRETS_PROVIDER?.toLowerCase();

    switch (provider) {
      case 'aws':
      case 'aws-secrets-manager':
        return new AWSSecretsManagerProvider();

      case 'vault':
      case 'hashicorp-vault':
        return new VaultProvider();

      case 'azure':
      case 'azure-key-vault':
        return new AzureKeyVaultProvider();

      case 'env':
      case 'environment':
        return new EnvironmentProvider();

      default:
        // Auto-detect based on environment
        if (process.env.AWS_EXECUTION_ENV || process.env.AWS_REGION) {
          return new AWSSecretsManagerProvider();
        }
        if (process.env.VAULT_ADDR) {
          return new VaultProvider();
        }
        if (process.env.AZURE_KEY_VAULT_URL) {
          return new AzureKeyVaultProvider();
        }

        // Fallback to environment variables with warning
        console.warn('⚠️  No secrets manager configured. Using environment variables.');
        console.warn('   Set SECRETS_PROVIDER to configure: aws, vault, azure, or env');
        return new EnvironmentProvider();
    }
  }

  async getSecret(name) {
    return this.provider.getSecret(name);
  }

  async getSecrets(names) {
    return this.provider.getSecrets(names);
  }

  /**
   * Get a database connection string securely
   * Strips sensitive components for logging
   */
  async getDatabaseUrl(secretName = 'database/credentials') {
    const credentials = await this.getSecret(secretName);

    // Support both full URL and individual components
    if (typeof credentials === 'string') {
      return credentials;
    }

    // Build URL from components
    const { host, port, database, username, password } = credentials;
    return `postgresql://${username}:${password}@${host}:${port}/${database}`;
  }

  /**
   * Redact a secret for safe logging
   */
  static redact(value, visibleChars = 4) {
    if (!value) return '[REDACTED]';
    if (value.length <= visibleChars) return '****';
    return `${value.substring(0, visibleChars)}${'*'.repeat(Math.min(value.length - visibleChars, 20))}`;
  }

  /**
   * Clear the secrets cache
   */
  clearCache() {
    secretsCache.clear();
  }
}

// Singleton instance
let instance = null;

function getSecretsManager() {
  if (!instance) {
    instance = new SecretsManager();
  }
  return instance;
}

module.exports = {
  SecretsManager,
  SecretProvider,
  EnvironmentProvider,
  AWSSecretsManagerProvider,
  VaultProvider,
  AzureKeyVaultProvider,
  getSecretsManager,
};

/**
 * Application Configuration using Secrets Manager
 * 
 * This module demonstrates how to securely load configuration
 * and secrets without using .env files in production.
 */

const { getSecretsManager } = require('./secrets');

// Configuration schema - defines what secrets are needed
const CONFIG_SCHEMA = {
  // Required secrets (app will fail to start if missing)
  required: [
    'DATABASE_URL',
  ],

  // Optional secrets (app will work with defaults)
  optional: {
    'NODE_ENV': 'development',
    'PORT': '3000',
    'HOST': '127.0.0.1',
    'ALLOWED_ORIGINS': 'https://yourdomain.com',
    'TRUST_PROXY': 'false',
  },
};

class AppConfig {
  constructor() {
    this.config = {};
    this.secretsManager = getSecretsManager();
    this.loaded = false;
  }

  /**
   * Load all configuration and secrets
   * Call this at application startup
   */
  async load() {
    if (this.loaded) {
      return this.config;
    }

    console.log('Loading application configuration...');

    // Load required secrets
    for (const key of CONFIG_SCHEMA.required) {
      try {
        this.config[key] = await this.secretsManager.getSecret(key);
        console.log(`✓ Loaded secret: ${key}`);
      } catch (error) {
        console.error(`✗ Failed to load required secret: ${key}`);
        throw new Error(`Missing required configuration: ${key}`);
      }
    }

    // Load optional secrets with defaults
    for (const [key, defaultValue] of Object.entries(CONFIG_SCHEMA.optional)) {
      try {
        this.config[key] = await this.secretsManager.getSecret(key);
        console.log(`✓ Loaded config: ${key}`);
      } catch (error) {
        this.config[key] = defaultValue;
        console.log(`✓ Using default for: ${key}`);
      }
    }

    // Validate configuration
    this.validate();

    this.loaded = true;
    return this.config;
  }

  /**
   * Validate configuration values
   */
  validate() {
    const errors = [];

    // Validate NODE_ENV
    const validEnvs = ['development', 'staging', 'production', 'test'];
    if (!validEnvs.includes(this.config.NODE_ENV)) {
      errors.push(`Invalid NODE_ENV: ${this.config.NODE_ENV}`);
    }

    // Validate PORT
    const port = parseInt(this.config.PORT, 10);
    if (isNaN(port) || port < 1 || port > 65535) {
      errors.push(`Invalid PORT: ${this.config.PORT}`);
    }

    // Validate DATABASE_URL format (basic check)
    if (this.config.DATABASE_URL) {
      try {
        const url = new URL(this.config.DATABASE_URL);
        if (!['postgresql:', 'postgres:', 'mysql:', 'mongodb:'].includes(url.protocol)) {
          errors.push(`Unsupported database protocol: ${url.protocol}`);
        }
      } catch (e) {
        errors.push('Invalid DATABASE_URL format');
      }
    }

    if (errors.length > 0) {
      throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
    }
  }

  /**
   * Get a configuration value
   * Never expose secrets through this method in logs or responses
   */
  get(key) {
    if (!this.loaded) {
      throw new Error('Configuration not loaded. Call load() first.');
    }
    return this.config[key];
  }

  /**
   * Get a redacted version of config for logging
   */
  getRedacted() {
    const redacted = { ...this.config };
    const sensitive = ['DATABASE_URL', 'API_KEY', 'SECRET', 'PASSWORD', 'TOKEN'];

    for (const key of Object.keys(redacted)) {
      if (sensitive.some(s => key.toUpperCase().includes(s))) {
        redacted[key] = '[REDACTED]';
      }
    }

    return redacted;
  }

  /**
   * Get database connection URL
   * Returns a sanitized version for logging
   */
  getDatabaseUrl() {
    return this.config.DATABASE_URL;
  }

  /**
   * Get sanitized database info for logging
   */
  getDatabaseInfo() {
    try {
      const url = new URL(this.config.DATABASE_URL);
      return {
        host: url.hostname,
        port: url.port,
        database: url.pathname.slice(1),
        user: url.username,
        // Never include password
      };
    } catch {
      return { error: 'Invalid database URL' };
    }
  }
}

// Singleton instance
let instance = null;

function getAppConfig() {
  if (!instance) {
    instance = new AppConfig();
  }
  return instance;
}

module.exports = {
  AppConfig,
  getAppConfig,
};

