/**
 * Secure Express Application
 * 
 * Security measures implemented:
 * - Helmet for security headers
 * - Rate limiting
 * - Input validation
 * - Error handling (no stack traces in production)
 * - CORS configuration
 * - Request size limits
 * - Logging
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ============================================
// Configuration
// ============================================
const config = {
  nodeEnv: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT, 10) || 3000,
  rateLimit: {
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // requests per window
  },
};

const isProduction = config.nodeEnv === 'production';

// ============================================
// Security Middleware
// ============================================

// Security headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:'],
    scriptSrc: ["'self'"],
    objectSrc: ["'none'"],
    frameAncestors: ["'none'"],
  },
}));

// CORS - configure properly for your needs
app.use(cors({
  origin: isProduction ? process.env.ALLOWED_ORIGINS?.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
}));

// Request size limits - prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimit.windowMs,
  max: config.rateLimit.max,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  // Use X-Forwarded-For header (set 'app.set('trust proxy', 1)' behind reverse proxy)
});
app.use('/api/', limiter);

// Disable framework information disclosure
app.disable('x-powered-by');

// Logging
morgan.token('user-id', (req) => req.user?.id || 'anonymous');
app.use(morgan(':date[iso] :method :url :status :user-id - :response-time ms'));

// ============================================
// Routes
// ============================================

// Health check - minimal info exposure
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    // Don't expose server version, internal IPs, or sensitive info
  });
});

// Users endpoint - with proper data handling
const sanitizeUser = (user) => ({
  id: user.id,
  name: user.name,
  // Consider if email should be public
