/**
 * Secure Secrets Configuration
 * 
 * This module provides a unified interface for loading secrets
 * from multiple backends:
 * - Development: Environment variables
 * - Production: Cloud secrets manager
 * - Kubernetes: Mounted secrets
 */

const fs = require('fs');
const path = require('path');

// Secret backends
const BACKEND_ENV = 'env';
const BACKEND_FILE = 'file'; // Kubernetes mounted secrets
const BACKEND_GCP = 'gcp';
const BACKEND_AWS = 'aws';

class SecretsConfig {
  constructor() {
    this.backend = this.detectBackend();
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Detect which secrets backend to use based on environment
   */
  detectBackend() {
    // Check for Kubernetes mounted secrets
    if (fs.existsSync('/var/secrets')) {
      return BACKEND_FILE;
    }

    // Check for cloud environment
    if (process.env.GOOGLE_CLOUD_PROJECT) {
      return BACKEND_GCP;
    }

    if (process.env.AWS_REGION || process.env.AWS_EXECUTION_ENV) {
      return BACKEND_AWS;
    }

    // Fallback to environment variables (development)
    return BACKEND_ENV;
  }

  /**
   * Get a secret value with caching
   */
  async get(key, options = {}) {
    const cacheKey = options.version ? `${key}:${options.version}` : key;

    // Check cache
    if (this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    // Fetch secret
    const value = await this.fetchSecret(key, options);

    // Cache it
    this.cache.set(cacheKey, { value, timestamp: Date.now() });

    // Log access (but not the value!)
    this.logSecretAccess(key, 'READ');

    return value;
  }

  /**
   * Fetch secret from appropriate backend
   */
  async fetchSecret(key, options = {}) {
    switch (this.backend) {
      case BACKEND_FILE:
        return this.fetchFromFile(key);

      case BACKEND_GCP:
        return this.fetchFromGCP(key, options.version);

      case BACKEND_AWS:
        return this.fetchFromAWS(key);

      case BACKEND_ENV:
      default:
        return this.fetchFromEnv(key);
    }
  }

  /**
   * Fetch from environment variable
   */
  fetchFromEnv(key) {
    const value = process.env[key];

    if (!value) {
      throw new SecretNotFoundError(
        `Secret '${key}' not found in environment variables. ` +
        `Make sure it's set in your .env file or environment.`
      );
    }

    return value;
  }

  /**
   * Fetch from Kubernetes mounted secret
   */
  fetchFromFile(key) {
    const secretPath = path.join('/var/secrets', key.toLowerCase());

    try {
      return fs.readFileSync(secretPath, 'utf8').trim();
    } catch (err) {
      throw new SecretNotFoundError(
        `Secret '${key}' not found at ${secretPath}`
      );
    }
  }

  /**
   * Fetch from Google Cloud Secret Manager
   */
  async fetchFromGCP(key, version = 'latest') {
    try {
      const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
      const client = new SecretManagerServiceClient();

      const projectId = process.env.GOOGLE_CLOUD_PROJECT;
      const name = `projects/${projectId}/secrets/${key}/versions/${version}`;

      const [response] = await client.accessSecretVersion({ name });
      return response.payload.data.toString();
    } catch (err) {
      if (err.code === 5) { // NOT_FOUND
        throw new SecretNotFoundError(`Secret '${key}' not found in GCP Secret Manager`);
      }
      throw err;
    }
  }

  /**
   * Fetch from AWS Secrets Manager
   */
  async fetchFromAWS(key) {
    try {
      const { SecretsManager } = require('@aws-sdk/client-secrets-manager');
      const client = new SecretsManager({ region: process.env.AWS_REGION });

      const response = await client.getSecretValue({ SecretId: key });

      if (response.SecretString) {
        return response.SecretString;
      }

      return Buffer.from(response.SecretBinary, 'base64').toString();
    } catch (err) {
      if (err.name === 'ResourceNotFoundException') {
        throw new SecretNotFoundError(`Secret '${key}' not found in AWS Secrets Manager`);
      }
      throw err;
    }
  }

  /**
   * Secure logging - never log secret values
   */
  logSecretAccess(key, action) {
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      event: 'SECRET_ACCESS',
      key: key,
      action: action,
      backend: this.backend,
      // NEVER log the value!
    }));
  }

  /**
   * Validate required secrets are available
   */
  async validateRequiredSecrets(requiredKeys) {
    const missing = [];

    for (const key of requiredKeys) {
      try {
        await this.get(key);
      } catch (err) {
        if (err instanceof SecretNotFoundError) {
          missing.push(key);
        } else {
          throw err;
        }
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}. ` +
        `Check your ${this.backend} configuration.`
      );
    }

    return true;
  }

  /**
   * Clear cache (useful for testing or rotation)
   */
  clearCache() {
    this.cache.clear();
  }
}

/**
 * Custom error for missing secrets
 */
class SecretNotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'SecretNotFoundError';
  }
}

/**
 * Validate secret strength
 */
const validateSecretStrength = (secret, minLength = 32) => {
  if (!secret || typeof secret !== 'string') {
    return { valid: false, message: 'Secret must be a non-empty string' };
  }

  if (secret.length < minLength) {
    return { 
      valid: false, 
      message: `Secret must be at least ${minLength} characters, got ${secret.length}` 
    };
  }

  // Check for common weak patterns
  const weakPatterns = [
    /^password$/i,
    /^secret$/i,
    /^test/i,
    /^CANARY/i,  // Canary secrets shouldn't be used in production!
  ];

  for (const pattern of weakPatterns) {
    if (pattern.test(secret)) {
      return { valid: false, message: 'Secret matches weak pattern' };
    }
  }

  return { valid: true };
};

// Singleton instance
const secretsConfig = new SecretsConfig();

module.exports = {
  secrets: secretsConfig,
  SecretNotFoundError,
  validateSecretStrength,
};

/**
 * Simple Express Application
 * 
 * Security improvements:
 * - Secure secrets loading
 * - Environment validation
 * - Security headers
 */

const express = require('express');
const helmet = require('helmet');
const { secrets, validateSecretStrength } = require('./config/secrets');

const app = express();

// ============================================
// Configuration
// ============================================
const config = {
  nodeEnv: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT, 10) || 3000,
};

const isProduction = config.nodeEnv === 'production';

// ============================================
// Security Middleware
// ============================================
app.use(helmet());
app.disable('x-powered-by');

// Request size limits
app.use(express.json({ limit: '10kb' }));

// ============================================
// Startup Validation
// ============================================
const validateStartup = async () => {
  // Validate required secrets exist
  const requiredSecrets = isProduction 
    ? ['DB_PASSWORD', 'JWT_SECRET']  // Production requires more secrets
    : [];  // Development is more lenient

  try {
    await secrets.validateRequiredSecrets(requiredSecrets);
  } catch (err) {
    console.error('Startup validation failed:', err.message);
    if (isProduction) {
      process.exit(1);
    } else {
      console.warn('Continuing in development mode without all secrets');
    }
  }

  // Validate secret strength in production
  if (isProduction) {
    const jwtSecret = await secrets.get('JWT_SECRET').catch(() => null);
    if (jwtSecret) {
      const strength = validateSecretStrength(jwtSecret, 32);
      if (!strength.valid) {
        console.error(`JWT_SECRET is weak: ${strength.message}`);
        process.exit(1);
      }
    }
  }
};

// Run validation before accepting requests
let startupComplete = false;
validateStartup()
  .then(() => {
    startupComplete = true;
    console.log('✓ Startup validation complete');
  })
  .catch(err => {
    console.error('Startup failed:', err);
    process.exit(1);
  });

// ============================================
// Routes
// ============================================

// Health check - readiness probe
app.get('/health', (req, res) => {
  if (!startupComplete) {
    return res.status(503).json({ 
      status: 'starting', 
      message: 'Server is initializing' 
    });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv,
    // Don't expose: secrets, versions, internal IPs, etc.
  });
});

// Users endpoint
app.get('/users', (req, res) => {
  // Sanitized user data - no internal fields
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// Example: Using secrets securely
// app.get('/api/data', async (req, res) => {
//   try {
//     const apiKey = await secrets.get('ANTHROPIC_API_KEY');
//     // Use apiKey to make request
//     // NEVER log or return the apiKey!
//     res.json({ success: true });
//   } catch (err) {
//     res.status(500).json({ error: 'Service unavailable' });
//   }
// });

// ============================================
// Error Handling
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error securely
  console.error({
    message: err.message,
    timestamp: new Date().toISOString(),
    path: req.path,
    // Don't log stack traces in production
    ...(isProduction ? {} : { stack: err.stack }),
  });

  // Sanitized error response
  res.status(err.status || 500).json({
    error: isProduction && err.status === 500 
      ? 'Internal Server Error' 
      : err.message,
  });
});

// ============================================
// Graceful Shutdown
// ============================================
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down...');
  process.exit(0);
});

// ============================================
// Start Server
// ============================================
if (require.main === module) {
  app.listen(config.port, () => {
    console.log(`Server running in ${config.nodeEnv} mode on port ${config.port}`);
  });
}

module.exports = app;

