const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.client = null;
  }

  async initialize() {
    if (process.env.NODE_ENV === 'production') {
      // Use cloud secrets manager
      this.client = new SecretManagerServiceClient();
    }
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    let secretValue;

    if (process.env.NODE_ENV === 'production') {
      // Fetch from secrets manager
      const [version] = await this.client.accessSecretVersion({
        name: `projects/${process.env.PROJECT_ID}/secrets/${secretName}/versions/latest`,
      });
      secretValue = version.payload.data.toString();
    } else {
      // Development: use environment with validation
      secretValue = process.env[secretName];
      if (!secretValue) {
        throw new Error(`Missing required secret: ${secretName}`);
      }
    }

    // Cache with TTL (5 minutes)
    this.cache.set(secretName, secretValue);
    setTimeout(() => this.cache.delete(secretName), 5 * 60 * 1000);

    return secretValue;
  }
}

module.exports = new SecretsManager();
