/**
 * Secure Express Application Template
 * 
 * This implements security best practices including:
 * - Security headers via Helmet
 * - Rate limiting
 * - CORS configuration
 * - Input validation
 * - Error handling
 * - Logging
 * - Environment-based configuration
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameSrc: ["'none'"],
      upgradeInsecureRequests: [],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// 2. CORS configuration
const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400,
};
app.use(cors(corsOptions));

// 3. Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later' },
});
app.use(apiLimiter);

// 4. Request logging
app.use(morgan('combined'));

// 5. Body parsing with size limits (prevents DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// DATA LAYER (Replace with actual database)
// ============================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================
// UTILITY FUNCTIONS
// ============================================

/**
 * Sanitize user data based on requester role
 * Implements data minimization principle
 */
const sanitizeUser = (user, requesterRole) => {
  const baseFields = { id: user.id, name: user.name };
  if (requesterRole === 'admin') {
    return { ...baseFields, email: user.email };
  }
  return baseFields;
};

/**
 * Async handler wrapper to catch errors
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// CUSTOM ERROR CLASSES
// ============================================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Authentication required') {
    super(message, 401);
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Insufficient permissions') {
    super(message, 403);
  }
}

class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

class ValidationError extends AppError {
  constructor(message = 'Validation failed') {
    super(message, 400);
  }
}

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

/**
 * Mock authentication middleware
 * Replace with actual JWT/session validation in production
 */
const authenticate = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader?.startsWith('Bearer ')) {
      throw new UnauthorizedError();
    }

    // In production, verify JWT token here
    const token = authHeader.split(' ')[1];

    // Mock user for demo purposes
    // Replace with actual token verification
    req.user = {
      id: 1,
      role: 'admin', // or 'user' based on token
    };

    next();
  } catch (error) {
    next(error);
  }
};

/**
 * Authorization middleware (role-based)
 */
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return next(new ForbiddenError());
    }
    next();
  };
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * No authentication required (for load balancers, monitoring)
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0',
  });
});

/**
 * Get all users
 * Requires authentication and admin role
 * Implements data minimization
 */
app.get('/users', 
  authenticate,
  authorize('admin'),
  asyncHandler(async (req, res) => {
    const sanitizedUsers = users.map(u => sanitizeUser(u, req.user.role));
    res.json(sanitizedUsers);
  })
);

/**
 * Get single user by ID
 * Demonstrates input validation on path parameters
 */
app.get('/users/:id',
  authenticate,
  asyncHandler(async (req, res) => {
    // Input validation
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid user ID');
    }

    const user = users.find(u => u.id === id);

    if (!user) {
      throw new NotFoundError('User not found');
    }

    // Users can only view their own data unless they're admin
    const isOwner = req.user.id === id;
    const isAdmin = req.user.role === 'admin';

    if (!isOwner && !isAdmin) {
      throw new ForbiddenError();
    }

    res.json(sanitizeUser(user, req.user.role));
  })
);

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error
  console.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Don't leak internal errors in production
  const isProduction = process.env.NODE_ENV === 'production';
  const isOperational = err.isOperational || false;

  res.status(statusCode).json({
    error: isOperational ? err.message : 'Internal server error',
    ...(isProduction ? {} : { 
      stack: err.stack,
      details: err.details,
    }),
  });
});

// ============================================
// PROCESS ERROR HANDLERS
// ============================================

process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('UNHANDLED REJECTION at:', promise, 'reason:', reason);
  process.exit(1);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

// Only start server if this is the main module
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

