/**
 * Secrets Management Module
 * 
 * Provides secure secret loading from multiple sources:
 * 1. AWS Secrets Manager (primary for production)
 * 2. HashiCorp Vault (alternative)
 * 3. Environment variables (development only)
 * 
 * Security features:
 * - Never logs secrets
 * - Caches with TTL for performance
 * - Validates secret existence
 * - Supports graceful fallback (dev only)
 */

const { SecretsManager } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

// ============================================
// CONFIGURATION
// ============================================

const SECRETS_CACHE_TTL = 3600000; // 1 hour in ms
const ENVIRONMENT = process.env.NODE_ENV || 'development';

// Cache for secrets to avoid repeated API calls
const secretsCache = new Map();

// ============================================
// SECRETS MANAGER CLIENTS
// ============================================

let awsSecretsManager = null;
let vaultClient = null;

/**
 * Initialize AWS Secrets Manager client
 */
function initAWSSecretsManager() {
  if (awsSecretsManager) return awsSecretsManager;

  // AWS SDK will use default credential chain:
  // 1. Environment variables (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY)
  // 2. Shared credentials file (~/.aws/credentials)
  // 3. EC2 Instance Profile
  // 4. ECS Task Role
  awsSecretsManager = new SecretsManager({
    region: process.env.AWS_REGION || 'us-east-1',
  });

  return awsSecretsManager;
}

/**
 * Initialize HashiCorp Vault client (alternative)
 */
async function initVaultClient() {
  if (vaultClient) return vaultClient;

  const vault = require('node-vault')({
    endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
    token: process.env.VAULT_TOKEN, // Should come from EC2/IAM auth in production
  });

  vaultClient = vault;
  return vaultClient;
}

// ============================================
// SECRET RETRIEVAL FUNCTIONS
// ============================================

/**
 * Get secret from AWS Secrets Manager
 * @param {string} secretId - The secret ID or ARN
 * @returns {Promise<object|string>} The secret value
 */
async function getAWSSecret(secretId) {
  const cacheKey = `aws:${secretId}`;

  // Check cache
  const cached = secretsCache.get(cacheKey);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.value;
  }

  try {
    const client = initAWSSecretsManager();
    const response = await client.getSecretValue({ SecretId: secretId });

    let secretValue;
    if (response.SecretString) {
      try {
        secretValue = JSON.parse(response.SecretString);
      } catch {
        secretValue = response.SecretString;
      }
    } else if (response.SecretBinary) {
      secretValue = Buffer.from(response.SecretBinary, 'base64');
    }

    // Cache the secret
    secretsCache.set(cacheKey, {
      value: secretValue,
      expiresAt: Date.now() + SECRETS_CACHE_TTL,
    });

    // Log access (without the secret value!)
    logSecretAccess(secretId, 'aws', 'success');

    return secretValue;
  } catch (error) {
    logSecretAccess(secretId, 'aws', 'failed', error.message);
    throw new Error(`Failed to retrieve secret ${secretId}: ${error.message}`);
  }
}

/**
 * Get secret from HashiCorp Vault
 * @param {string} path - The vault path
 * @returns {Promise<object>} The secret value
 */
async function getVaultSecret(path) {
  const cacheKey = `vault:${path}`;

  // Check cache
  const cached = secretsCache.get(cacheKey);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.value;
  }

  try {
    const vault = await initVaultClient();
    const response = await vault.read(path);

    if (!response?.data?.data) {
      throw new Error('Invalid vault response');
    }

    const secretValue = response.data.data;

    // Cache the secret
    secretsCache.set(cacheKey, {
      value: secretValue,
      expiresAt: Date.now() + SECRETS_CACHE_TTL,
    });

    logSecretAccess(path, 'vault', 'success');

    return secretValue;
  } catch (error) {
    logSecretAccess(path, 'vault', 'failed', error.message);
    throw new Error(`Failed to retrieve secret from vault at ${path}: ${error.message}`);
  }
}

/**
 * Get secret from environment variable (development only!)
 * @param {string} key - The environment variable name
 * @returns {string|undefined} The secret value
 */
function getEnvSecret(key) {
  if (ENVIRONMENT === 'production') {
    console.warn(`⚠️  WARNING: Attempting to load secret '${key}' from environment in production!`);
  }
  return process.env[key];
}

// ============================================
// SECURITY LOGGING
// ============================================

function logSecretAccess(secretId, source, status, error = null) {
  // Never log the actual secret value!
  const logEntry = {
    event: 'secret_access',
    secret_id: secretId,
    source,
    status,
    timestamp: new Date().toISOString(),
    environment: ENVIRONMENT,
    ...(error && { error: error }),
  };

  // In production, send to SIEM/monitoring
  console.log(JSON.stringify(logEntry));
}

// ============================================
// MAIN SECRET LOADING FUNCTION
// ============================================

/**
 * Load application secrets from appropriate source based on environment
 * @returns {Promise<object>} Object containing all application secrets
 */
async function loadSecrets() {
  let secrets = {};

  if (ENVIRONMENT === 'production') {
    // PRODUCTION: Load from secrets manager
    console.log('📦 Loading secrets from AWS Secrets Manager...');

    try {
      // Load database credentials
      const dbSecrets = await getAWSSecret('production/database');
      secrets.DATABASE_URL = dbSecrets.connection_string || 
        `postgres://${dbSecrets.username}:${dbSecrets.password}@${dbSecrets.host}:${dbSecrets.port}/${dbSecrets.database}`;

      // Load Stripe key
      const stripeSecrets = await getAWSSecret('production/stripe');
      secrets.STRIPE_SECRET_KEY = stripeSecrets.secret_key;
      secrets.STRIPE_WEBHOOK_SECRET = stripeSecrets.webhook_secret;

      // Load API keys
      const apiSecrets = await getAWSSecret('production/api-keys');
      secrets.ANTHROPIC_API_KEY = apiSecrets.anthropic_key;
      secrets.LOGFIRE_TOKEN = apiSecrets.logfire_token;

      // AWS credentials should come from IAM role, not secrets manager
      // But if needed:
      // const awsSecrets = await getAWSSecret('production/aws');
      // secrets.AWS_ACCESS_KEY_ID = awsSecrets.access_key_id;
      // secrets.AWS_SECRET_ACCESS_KEY = awsSecrets.secret_access_key;

    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      throw error;
    }

  } else if (ENVIRONMENT === 'development') {
    // DEVELOPMENT: Load from environment with validation
    console.log('📦 Loading secrets from environment variables...');

    // Warn about missing secrets
    const requiredSecrets = [
      'DATABASE_URL',
      'STRIPE_SECRET_KEY',
    ];

    const missingSecrets = requiredSecrets.filter(s => !process.env[s]);
    if (missingSecrets.length > 0) {
      console.warn(`⚠️  Missing secrets: ${missingSecrets.join(', ')}`);
      console.warn('   Some features may not work correctly.');
    }

    // Load from environment
    secrets = {
      DATABASE_URL: process.env.DATABASE_URL,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      STRIPE_WEBHOOK_SECRET: process.env.STRIPE_WEBHOOK_SECRET,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
    };

  } else if (ENVIRONMENT === 'test') {
    // TEST: Use mock/seeded secrets
    console.log('📦 Loading test secrets...');

    secrets = {
      DATABASE_URL: 'postgres://test:test@localhost:5432/test',
      STRIPE_SECRET_KEY: 'sk-test-mock_key',
      STRIPE_WEBHOOK_SECRET: 'whsec_test',
      ANTHROPIC_API_KEY: 'sk-ant-test-key',
      LOGFIRE_TOKEN: 'test_token',
    };
  }

  // Validate critical secrets exist
  validateSecrets(secrets);

  return secrets;
}

/**
 * Validate that required secrets are present
 */
function validateSecrets(secrets) {
  const criticalSecrets = ['DATABASE_URL'];

  for (const key of criticalSecrets) {
    if (!secrets[key]) {
      throw new Error(`Critical secret '${key}' is missing!`);
    }
  }

  // Warn about production Stripe key in non-production
  if (ENVIRONMENT !== 'production' && secrets.STRIPE_SECRET_KEY?.startsWith('sk-live-')) {
    throw new Error('PRODUCTION Stripe key detected in non-production environment!');
  }

  console.log('✅ Secrets validated successfully');
}

// ============================================
// SECRET HELPER FUNCTIONS
// ============================================

/**
 * Clear the secrets cache (useful for rotation)
 */
function clearSecretsCache() {
  secretsCache.clear();
  console.log('🗑️  Secrets cache cleared');
}

/**
 * Verify a secret against a hash (for webhook signatures, etc.)
 */
function verifySecretSignature(payload, signature, secret) {
  const expectedSignature = crypto
    .createHmac('sha256', secret)
    .update(payload)
    .digest('hex');

  return crypto.timingSafeEqual(
    Buffer.from(signature),
    Buffer.from(expectedSignature)
  );
}

// ============================================
// EXPORTS
// ============================================

module.exports = {
  loadSecrets,
  getAWSSecret,
  getVaultSecret,
  getEnvSecret,
  clearSecretsCache,
  verifySecretSignature,
  validateSecrets,
};

/**
 * Secure Express Application with Secrets Management
 * 
 * Demonstrates proper secrets loading:
 * - Production: AWS Secrets Manager
 * - Development: Environment variables
 * - Test: Mock secrets
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { loadSecrets } = require('./secrets');

const app = express();

// ============================================
// STARTUP: Load Secrets
// ============================================

let secrets;

async function initializeApp() {
  try {
    // Load secrets BEFORE setting up routes that need them
    secrets = await loadSecrets();

    console.log('🔐 Secrets loaded successfully');
    console.log('   Environment:', process.env.NODE_ENV || 'development');

    // Now start the server
    startServer();
  } catch (error) {
    console.error('❌ Failed to initialize app:', error.message);
    process.exit(1);
  }
}

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers
app.use(helmet());

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
}));

// Logging
app.use(morgan('combined'));

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    secretsLoaded: !!secrets,
  });
});

app.get('/users', (req, res) => {
  // Demo: This would use secrets.DATABASE_URL to connect to DB
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example: Route that uses Stripe secret
app.post('/webhook/stripe', express.raw({ type: 'application/json' }), (req, res) => {
  const sig = req.headers['stripe-signature'];

  // Use the loaded secret for webhook verification
  try {
    // In production, verify with secrets.STRIPE_WEBHOOK_SECRET
    console.log('Webhook received, signature:', sig?.substring(0, 20) + '...');
    res.json({ received: true });
  } catch (error) {
    res.status(400).json({ error: 'Invalid signature' });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

app.use((err, req, res, next) => {
  console.error({
    message: err.message,
    path: req.path,
    timestamp: new Date().toISOString(),
  });

  res.status(err.statusCode || 500).json({
    error: err.isOperational ? err.message : 'Internal server error',
  });
});

// ============================================
// SERVER STARTUP
// ============================================

function startServer() {
  const PORT = process.env.PORT || 3000;

  app.listen(PORT, () => {
    console.log(`🚀 Server running on port ${PORT}`);
  });
}

// ============================================
// PROCESS LIFECYCLE
// ============================================

process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('UNHANDLED REJECTION:', reason);
  process.exit(1);
});

// Graceful shutdown for secrets cleanup
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  // Could clear secrets cache here
  process.exit(0);
});

// ============================================
// INITIALIZE
// ============================================

initializeApp();

module.exports = app;

/**
 * Rotation Tracking Webhook Integration
 * 
 * This demonstrates SECURE integration with compliance systems.
 * 
 * IMPORTANT: We send STATUS only, NEVER credential values.
 */

const https = require('https');

/**
 * Report rotation status to compliance webhook
 * Sends ONLY metadata - no credential values
 */
async function reportRotationStatus(config) {
  const payload = {
    event: 'credential_rotation',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    status: config.status, // 'started' | 'completed' | 'failed'
    rotated_by: config.rotatedBy,

    // List of secrets rotated - ONLY NAMES, NOT VALUES
    secrets: [
      { name: 'DATABASE_URL', rotated: true, timestamp: new Date().toISOString() },
      { name: 'AWS_ACCESS_KEY_ID', rotated: true, timestamp: new Date().toISOString() },
      { name: 'AWS_SECRET_ACCESS_KEY', rotated: true, timestamp: new Date().toISOString() },
      { name: 'ANTHROPIC_API_KEY', rotated: true, timestamp: new Date().toISOString() },
      { name: 'STRIPE_SECRET_KEY', rotated: true, timestamp: new Date().toISOString() },
      { name: 'LOGFIRE_TOKEN', rotated: true, timestamp: new Date().toISOString() },
    ],

    // Compliance tracking
    rotation_id: generateRotationId(),
    policy: 'quarterly-rotation',

    // Note: We send hash signatures, not values
    previous_version_sha256: config.previousVersionHash, // Hash, not value!
    new_version_sha256: config.newVersionHash, // Hash, not value!
  };

  return sendToWebhook(payload);
}

/**
 * Send payload to compliance webhook
 */
async function sendToWebhook(payload) {
  const webhookUrl = process.env.COMPLIANCE_WEBHOOK_URL;

  if (!webhookUrl) {
    console.warn('⚠️  COMPLIANCE_WEBHOOK_URL not configured, skipping report');
    return;
  }

  // Validate URL is internal/authorized
  const url = new URL(webhookUrl);
  if (!url.hostname.endsWith('.internal.company.com')) {
    throw new Error('Compliance webhook must be an internal endpoint');
  }

  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);

    const options = {
      hostname: url.hostname,
      port: url.port || 443,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'Authorization': `Bearer ${process.env.COMPLIANCE_API_KEY}`,
      },
    };

    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✅ Rotation status reported to compliance system');
          resolve(body);
        } else {
          reject(new Error(`Webhook failed: ${res.statusCode}`));
        }
      });
    });

    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

/**
 * Generate unique rotation ID for tracking
 */
function generateRotationId() {
  return `rot_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

module.exports = {
  reportRotationStatus,
};

