      SecretId: 'production/database',
    });

    const stripeSecret = await client.getSecretValue({
      SecretId: 'production/stripe',
    });

    cachedSecrets = {
      database: JSON.parse(dbSecret.SecretString),
      stripe: JSON.parse(stripeSecret.SecretString),
    };

    return cachedSecrets;
  } catch (error) {
    console.error('Failed to load secrets:', error);
    throw error;
  }
}

// Graceful shutdown - clear secrets from memory
process.on('SIGTERM', () => {
  if (cachedSecrets) {
    cachedSecrets = null;
  }
});

