function detectCanaryUsage(value, context) {
  if (CANARY_PATTERN.test(value)) {
    console.error(`[SECURITY ALERT] Canary token used in ${context}`);
    // Trigger alert to security team
    alertSecurityTeam({ type: 'canary_usage', context, timestamp: Date.now() });
  }
}
